// Picks one unused photo for today's format and reserves it in the ledger.
// Each run produces only one format: the trigger that fired decides post vs story.
const fs = require('fs');
const crypto = require('crypto');
const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const ROOT = CFG.data_dir;
const STATE = ROOT + '/state';
const ledgerPath = STATE + '/ledger.json';
const kind = $('Post Schedule').isExecuted ? 'post' : 'story';
fs.mkdirSync(STATE, {recursive: true});
let ledger = {version: 1, entries: []};
if (fs.existsSync(ledgerPath)) ledger = JSON.parse(fs.readFileSync(ledgerPath, 'utf8'));
if (!Array.isArray(ledger.entries)) throw new Error('Ledger is corrupt: ' + ledgerPath);
let menuNames = [];
try { menuNames = JSON.parse(fs.readFileSync(STATE + '/menu.json', 'utf8')).items || []; } catch (e) {}
if (!menuNames.length) throw new Error('Menu list is empty: add your publishable products to ' + STATE + '/menu.json');
let overrides = {};
try { overrides = JSON.parse(fs.readFileSync(STATE + '/photo_overrides.json', 'utf8')); } catch (e) {}
// Persistent photo -> dish catalog: verified names always win over the AI guess
let catalog = {};
try { catalog = JSON.parse(fs.readFileSync(STATE + '/photo_dishes.json', 'utf8')).photos || {}; } catch (e) {}
// Photos the owner rejected are never picked
const skipped = new Set(Object.keys(catalog).filter(f => (catalog[f] || {}).source === 'skipped'));
const catalogDishOf = f => {
  const e = catalog[f];
  if (!e || !e.dish) return '';
  return (e.source === 'confirmed' || e.source === 'ai_consensus') ? e.dish : '';
};
// A photo is "used" once it has a ledger entry - except dry runs, and review cases that now have an override
const retry = e => e.status === 'review' && overrides[e.sourceFile];
const used = new Set(ledger.entries.filter(e => !retry(e) && e.status !== 'dry_run').map(e => e.hash).filter(Boolean));
const corrected = new Set(ledger.entries.filter(retry).map(e => e.sourceFile));
const options = [];
for (const folder of (CFG.photo_folders || ['photos'])) {
  const dir = ROOT + '/' + folder;
  if (!fs.existsSync(dir)) continue;
  for (const file of fs.readdirSync(dir).filter(x => /\.(jpe?g|png|webp)$/i.test(x) && !/logo/i.test(x)).sort()) {
    if (skipped.has(file)) continue;
    const full = dir + '/' + file;
    const hash = crypto.createHash('sha256').update(fs.readFileSync(full)).digest('hex');
    if (!used.has(hash)) options.push({file, full, hash});
  }
}
// Nothing left to publish: the run ends quietly (add more photos)
if (!options.length) return [];
const correctedOptions = options.filter(o => corrected.has(o.file));
// Prefer photos whose dish is already known, so photos with a naming risk wait
const knownOptions = options.filter(o => catalogDishOf(o.file));
const pool = correctedOptions.length ? correctedOptions : (knownOptions.length ? knownOptions : options);
const selected = pool[Math.floor(Math.random() * pool.length)];
// The tone "angle" must fit the product type: a soup has no grill marks
const dishName = catalogDishOf(selected.file) || overrides[selected.file] || '';
const toRe = m => { try { return new RegExp(m, 'iu'); } catch (e) { return null; } };
const sets = Array.isArray(CFG.angle_sets) ? CFG.angle_sets : [];
const set = sets.find(s => s.match && toRe(s.match) && toRe(s.match).test(dishName)) || sets.find(s => !s.match) || {angles: ['close-up']};
const angles = set.angles;
const recent = ledger.entries.slice(-5).map(e => e.angle);
const angle = angles.find(a => !recent.includes(a)) || angles[ledger.entries.length % angles.length];
const base = 'auto_' + kind + '_' + Date.now() + '_' + selected.hash.slice(0, 8);
const catalogDish = catalogDishOf(selected.file);
ledger.entries.push({base, kind, hash: selected.hash, sourceFile: selected.file, angle, status: 'reserved', createdAt: new Date().toISOString()});
const tmp = ledgerPath + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(ledger, null, 2)); fs.renameSync(tmp, ledgerPath);
return [{json: {base, kind, rawPath: selected.full, sourceFile: selected.file, sourceHash: selected.hash, angle, menuNames, catalogDish, overrideDish: overrides[selected.file] || ''}}];

// Loads the photo as binary for Gemini and builds the analysis prompt.
const fs = require('fs');
const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const j = $json;
const p = j.rawPath;
const ext = (p.split('.').pop() || 'jpg').toLowerCase();
const mime = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';
const binary = await this.helpers.prepareBinaryData(fs.readFileSync(p), j.sourceFile, mime);
const maxW = CFG.title_max_words || 5, maxC = CFG.title_max_chars || 44;
const banned = (CFG.banned_phrases || []).join(', ');
const examples = (CFG.style_examples || []).map(s => '"' + s + '"').join(', ');
let dishRule;
if (j.catalogDish) dishRule = 'The dish in this photo is DEFINITELY: ' + j.catalogDish + '. Write exactly this in the dish field and set confidence to 1; do not guess the dish again.';
else if (j.overrideDish) dishRule = 'The owner corrected the dish to: ' + j.overrideDish + '. Write exactly this in the dish field and set confidence to 1.';
else dishRule = 'In the dish field, choose the SPECIFIC product shown in the photo from this list: ' + j.menuNames.join(' | ') + '. Do not choose a category name, a generic product name or an ambiguous dish; if you are not sure, leave dish empty. confidence is your recognition confidence between 0 and 1: give more than 0.90 only when there is distinctive visual evidence.';
const prompt = [
  'You write Instagram copy for ' + CFG.brand_name + ' (' + (CFG.brand_context || 'a restaurant') + '). Judge the photo only by what is visibly in it. Write natural, varied copy in ' + LANG + '. Tone focus: ' + j.angle + '.',
  dishRule,
  'In the visible field, list 4-10 short items that are CLEARLY visible in the photo: foods, garnishes, drinks and serving items (plate, board, bowl, type of bread included); do not add anything you are unsure about.',
  'In the scene field, describe in one objective sentence what the main dish looks like and how it is served (for example the kind of meat, fish or vegetable, whether it is on a skewer, in a wrap or flatbread, on a plate, or in a soup bowl).',
  'Do NOT use menu product names in the visible and scene fields; only describe what you see.',
  'In the options field, write THREE CLEARLY DIFFERENT alternatives. In each alternative:',
  'redTitle = the white headline printed on the image. It is about the main dish itself (its taste, texture, cooking), appetizing, at most ' + maxW + ' words and ' + maxC + ' characters, a complete phrase in sentence case, WITHOUT the dish name (the dish name is printed on its own line below it). Do not make a garnish or the plate the subject of the headline.',
  examples ? 'Tone examples (do not copy them, only take the tone): ' + examples + '.' : '',
  'caption = 1-2 short sentences, at least 40 characters. It mentions the dish by its short name (without anything in parentheses) naturally inside a sentence, not in Title Case, and contains only details verified in the photo. Describe visible texture, grill marks, freshness or a distinct garnish if they are really there; do not list serving items such as plates, bowls or glasses; do not repeat the brand name.',
  banned ? 'Never use these words or phrases in any alternative: ' + banned + '.' : '',
  'Write nothing but JSON: {"dish":"the exact specific name from the list","confidence":0.0,"visible":["..."],"scene":"...","options":[{"redTitle":"...","caption":"..."},{"redTitle":"...","caption":"..."},{"redTitle":"...","caption":"..."}]}.',
  'Do not invent prices, discounts, promotions, opening hours, addresses, phone numbers, ingredients or any feature that is not verified in the photo. No emoji, no hashtags.'
].filter(Boolean).join(' ');
return [{json: {...j, analysisPrompt: prompt}, binary: {data: binary}}];

// Gate 1 (deterministic): dish identity + rule-based copy checks, before any judge sees the copy.
const fs = require('fs');
const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
// ---- Rule-based copy checks (deterministic, run before the judge) ----
const norm = s => String(s || '').trim().toLocaleLowerCase(LOC);
const clean = s => String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
const reEsc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// Unicode-aware word boundaries (JavaScript's \b only knows ASCII letters)
const phraseRe = list => { const l = (list || []).filter(Boolean); return l.length ? new RegExp('(?<![\\p{L}\\p{N}])(?:' + l.map(reEsc).join('|') + ')(?![\\p{L}\\p{N}])', 'iu') : null; };
const prohibited = CFG.prohibited_pattern ? new RegExp(CFG.prohibited_pattern, 'iu') : null; // prices, promotions, times...
const cliche = phraseRe(CFG.banned_phrases);
const TITLE_MAX_WORDS = CFG.title_max_words || 5, TITLE_MAX_CHARS = CFG.title_max_chars || 44;
// Name the reason a candidate was dropped: it is stored in the ledger and shown in the email
const why = (c, t, shortDish, recentCaps) => {
  if (!c) return 'caption empty';
  if (c.length < 35) return 'caption too short';
  if (c.length > 350) return 'caption too long';
  if (!norm(c).includes(norm(shortDish))) return 'dish name missing from caption';
  if (!t) return 'headline empty';
  if (t.length > TITLE_MAX_CHARS) return 'headline too long';
  if (t.split(/\s+/).length > TITLE_MAX_WORDS) return 'headline has more than ' + TITLE_MAX_WORDS + ' words';
  // The dish name is already printed on the product line right below the headline
  if (norm(t).includes(norm(shortDish))) return 'headline repeats the dish name';
  if (prohibited && prohibited.test(c + ' ' + t)) return 'prohibited phrase (price/promotion etc.)';
  if (cliche && cliche.test(c + ' ' + t)) return 'banned cliché';
  if (recentCaps.includes(norm(c))) return 'repeats a recent caption';
  return '';
};
const normalizeCand = (o, dish, shortDish) => ({
  redTitle: clean(o && o.redTitle).replace(/[.!…]+$/, ''),
  caption: clean(o && o.caption).split(dish).join(shortDish)
});
const src = $('Read Photo').first().json;
const path = CFG.data_dir + '/state/ledger.json';
const ledger = JSON.parse(fs.readFileSync(path, 'utf8'));
const entry = ledger.entries.find(e => e.base === src.base);
if (!entry) throw new Error('Ledger entry not found: ' + src.base);
const save = () => { const tmp = path + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(ledger, null, 2)); fs.renameSync(tmp, path); };
let text = ''; try { text = $json.content.parts[0].text || ''; } catch (e) {}
if (!text && $json.text) text = $json.text;
text = String(text).replace(/```(?:json)?/gi, '').trim();
let ai; try { ai = JSON.parse(text); } catch (e) { ai = {}; }

const menu = new Set(src.menuNames.map(norm));
// Priority: user override > verified catalog > AI guess
const trusted = clean(src.overrideDish || src.catalogDish);
const dish = trusted || clean(ai.dish);
const confidence = Number(ai.confidence);
const reviewPath = CFG.data_dir + '/state/photo_overrides.json';
const reviewOut = (reason, suggested) => {
  entry.status = 'review'; entry.reason = reason; entry.suggestedDish = suggested;
  entry.confidence = Number.isFinite(confidence) ? confidence : null; save();
  return [{json: {reviewNeeded: true, reason, sourceFile: src.sourceFile, suggestedDish: suggested, confidence: entry.confidence, reviewPath}}];
};
// Product identity is never delegated to Jev: it cannot see the photo, and picking the dish
// from Gemini's text description was unreliable in testing.
if (!menu.has(norm(dish)) || (!trusted && (!Number.isFinite(confidence) || confidence < 0.9))) {
  return reviewOut('Dish could not be recognised with confidence', clean(ai.dish));
}
const shortDish = dish.replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
const recentCaps = ledger.entries.filter(e => e.status === 'published').slice(-5).map(e => norm(e.caption));
// The model writes three alternatives; ALL that pass the rules go to Jev and the best one wins there
const raw = Array.isArray(ai.options) && ai.options.length ? ai.options : [{redTitle: ai.redTitle, caption: ai.caption}];
const candidates = [], codeFails = [];
raw.forEach((o, i) => {
  const c = normalizeCand(o, dish, shortDish);
  const w = why(c.caption, c.redTitle, shortDish, recentCaps);
  if (w) codeFails.push({...c, round: 1, fail: w}); else candidates.push({...c, round: 1, id: '1.' + (i + 1)});
});
const visible = Array.isArray(ai.visible) ? ai.visible.map(clean).filter(Boolean).slice(0, 12) : [];
entry.status = 'checked'; entry.dish = dish; entry.confidence = Number.isFinite(confidence) ? confidence : null;
entry.dishSource = src.overrideDish ? 'override' : (src.catalogDish ? 'catalog' : 'ai'); save();
return [{json: {reviewNeeded: false, base: src.base, kind: src.kind, sourceFile: src.sourceFile, angle: src.angle, dish, shortDish,
  dishSource: entry.dishSource, confidence: entry.confidence, visible, scene: clean(ai.scene), candidates, codeFails}}];

const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
// ---- Jev (TypeSafe) shared definitions: a typed decision model. It never writes text and never sees images. ----
const JEV_MODEL = CFG.jev_model || 'typesafe/jev-1.13';
const JEV_ON = CFG.jev_enabled !== false;
const Q_OK = Number(CFG.jev_min_score) || 0.80; // best candidate below this score triggers one revision round
const TMAXW = CFG.title_max_words || 5;
const productLine = d => { const s = d.shortDish || ''; const p = String(CFG.product_prefix || '').trim(); return p && !s.toLocaleLowerCase(LOC).startsWith(p.toLocaleLowerCase(LOC)) ? p + ' ' + s : s; };
const jevQuestions = (kind) => {
  const q = {
    dish_match: {type: 'noul', instructions: 'The white headline (title) and the caption are Instagram copy for the restaurant dish named in "dish". Do they describe that dish (as presented in "presentation") and not a different food?', criteria: {true: 'Text is about the named dish', false: 'Text describes a different dish or contradicts the named dish'}},
    title_grammar: {type: 'score', instructions: 'Rate the ' + LANG + ' grammar and naturalness of the title (a short headline, max ' + TMAXW + ' words). A headline may be a noun phrase, but it must be complete and idiomatic; a dangling or cut-off ending, a wrong inflection or an odd word combination counts as broken.', criteria: ['broken or incomplete ' + LANG, 'awkward or unnatural', 'correct but plain', 'natural, fluent ' + LANG]},
    title_focus: {type: 'noul', instructions: 'Is the title mainly about the main dish itself (its taste, texture, cooking, freshness or appetite appeal) rather than mainly about a side item, garnish, pickle, drink, plate or camera angle?', criteria: {true: 'Focused on the main dish', false: 'Mainly about a side item, garnish, prop or the photo itself'}},
    title_appeal: {type: 'score', instructions: 'How appetizing and specific is the title as a food advertising headline for ' + (CFG.brand_context || 'a restaurant') + '?', criteria: ['generic or dull', 'acceptable', 'appetizing', 'very appetizing and specific']},
    main_issue: {type: 'choice', instructions: 'What is the single most important problem with this copy?', criteria: {
      none: 'No real problem, ready to publish',
      grammar: LANG + ' grammar/spelling error or unnatural wording',
      incomplete_title: 'Title is an incomplete or dangling phrase',
      off_focus: 'Title focuses on a side item, garnish or prop instead of the dish',
      ungrounded: 'Mentions a food or detail not listed in visible_in_photo',
      cliche: 'Generic cliché advertising phrases',
      dish_mismatch: 'Describes a different dish than the named one',
      repeats_dish: 'Title repeats the dish name, which is already printed on the product line below it'}}
  };
  if (kind === 'post') {
    q.caption_grammar = {type: 'score', instructions: 'Rate the ' + LANG + ' grammar and naturalness of the caption.', criteria: ['broken ' + LANG, 'awkward or unnatural', 'correct but plain', 'natural, fluent ' + LANG]};
    q.caption_grounded = {type: 'noul', instructions: 'Is every specific food, side dish, drink, sauce or serving detail mentioned in the caption supported by the visible_in_photo list or presentation (synonyms allowed)?', criteria: {true: 'Everything mentioned is visible', false: 'Mentions something that is not in the visible list'}};
    q.caption_appeal = {type: 'score', instructions: 'How appetizing and engaging is the caption for Instagram food marketing? Listing plates, bowls or cups is dull; vivid, specific description of the dish is good.', criteria: ['dull or list-like', 'acceptable', 'appetizing', 'very appetizing and vivid']};
  }
  return q;
};
const jevBody = (d, c) => {
  const s = {brand: CFG.brand_name + ' - ' + (CFG.brand_context || 'a restaurant') + ' (Instagram account)', format: d.kind === 'post' ? 'feed post' : 'story (only the title is shown, no caption)',
    dish: d.dish, presentation: d.scene || '', visible_in_photo: d.visible || [],
    layout: 'The title is printed in white on the photo; directly below it the product line "' + productLine(d) + '" is printed in the accent colour.', title: c.redTitle};
  if (d.kind === 'post') s.caption = c.caption; else s.caption_for_context_only = c.caption;
  return {model: JEV_MODEL, state: s, questions: jevQuestions(d.kind)};
};
const PING = {model: JEV_MODEL, state: 'connectivity check', questions: {ok: {type: 'noul', instructions: 'Is this a connectivity check?', criteria: {true: 'yes', false: 'no'}}}};
// Jev diagnoses -> revision instructions for the writer model
const DIRECTIVES = {
  grammar: 'There is a ' + LANG + ' grammar or naturalness problem; use fluent, natural ' + LANG + '.',
  incomplete_title: 'The headline is an unfinished phrase; write a complete headline that makes sense on its own (no dangling endings).',
  off_focus: 'The headline is about a garnish, side item, plate or camera angle instead of the main dish; make it describe the taste, texture, cooking or appetite appeal of the main dish itself.',
  ungrounded: 'Something is mentioned that is not visible in the photo; only use items from the visible list.',
  cliche: 'The wording is generic, clichéd advertising language; use a specific, concrete and fresh phrase for this dish.',
  dish_mismatch: 'The text describes a different dish; describe only the named dish.',
  repeats_dish: 'The headline repeats the dish name; the dish name is already printed below it, so do not use it in the headline.',
  appeal: 'The headline is not appetizing or specific enough; lead with the most attractive visible quality of the dish.',
  caption_grammar: 'The caption is grammatically broken or unnatural; write two short, fluent, natural sentences.',
  caption_appeal: 'The caption reads like a list or is flat; instead of listing serving items, describe the dish vividly and appetizingly.',
  title_grammar: 'The headline is grammatically broken or artificial; write a natural ' + LANG + ' headline.'
};
const LABELS = {dish_mismatch: 'dish mismatch', title_grammar: 'broken headline language', caption_grammar: 'broken caption language', ungrounded: 'detail not in photo',
  off_focus: 'headline not about the dish', appeal: 'flat headline', caption_appeal: 'flat caption', grammar: 'grammar', incomplete_title: 'unfinished headline',
  cliche: 'cliché', repeats_dish: 'repeats dish name'};
// Weighted quality score (0..1) + hard gates. main_issue is only a revision hint, never a gate:
// in testing it always picked *some* issue (usually "cliche"), even for good copy.
const evaluate = (kind, A) => {
  const g = (k, f) => A[k] ? A[k][f] : null;
  const r = {dish: g('dish_match', 'noul'), tg: g('title_grammar', 'score'), tf: g('title_focus', 'noul'), ta: g('title_appeal', 'score'),
    issue: g('main_issue', 'choice'), issueP: A.main_issue && A.main_issue.probabilities ? (A.main_issue.probabilities[A.main_issue.choice] || 0) : 0,
    cg: g('caption_grammar', 'score'), gr: g('caption_grounded', 'noul'), ca: g('caption_appeal', 'score')};
  const gates = [];
  if (r.dish < 0.5) gates.push('dish_mismatch');
  if (r.tg < 1.5) gates.push('title_grammar');
  if (kind === 'post') { if (r.cg < 1.5) gates.push('caption_grammar'); if (r.gr < 0.35) gates.push('ungrounded'); }
  const q = kind === 'post'
    ? 0.25 * r.tf + 0.25 * r.ta / 3 + 0.15 * r.tg / 3 + 0.15 * r.cg / 3 + 0.10 * r.gr + 0.10 * r.ca / 3
    : 0.35 * r.tf + 0.40 * r.ta / 3 + 0.25 * r.tg / 3;
  const diag = new Set();
  if (r.tg < 2) diag.add('title_grammar');
  if (r.tf < 0.5) diag.add('off_focus');
  if (r.ta < 1.5) diag.add('appeal');
  if (kind === 'post') { if (r.cg < 2) diag.add('caption_grammar'); if (r.gr < 0.5) diag.add('ungrounded'); if (r.ca < 1.5) diag.add('caption_appeal'); }
  if (r.dish < 0.5) diag.add('dish_mismatch');
  if (r.issue && r.issue !== 'none' && r.issueP >= 0.5 && DIRECTIVES[r.issue]) diag.add(r.issue);
  return {...r, q: Math.round(q * 1000) / 1000, gates, ok: gates.length === 0, diag: [...diag]};
};
const revisionPrompt = (d, rated, fails) => {
  const lines = [];
  rated.forEach((c, i) => {
    const probs = (c.diag || []).map(x => DIRECTIVES[x]).filter(Boolean).join(' ') || 'no clear problem';
    lines.push((i + 1) + ') Headline: "' + c.redTitle + '" | Caption: "' + c.caption + '" | Quality score: ' + (c.q == null ? '?' : Math.round(c.q * 100)) + '/100 | Problems: ' + probs);
  });
  (fails || []).forEach(c => lines.push('- Candidate rejected by the rules: "' + c.redTitle + '" / "' + c.caption + '" -> ' + c.fail));
  const banned = (CFG.banned_phrases || []).join(', ');
  return 'Copy candidates written for an Instagram ' + (d.kind === 'post' ? 'feed post' : 'story') + ' of ' + CFG.brand_name + ' (' + (CFG.brand_context || 'a restaurant') + ') went through an independent quality review. ' +
    'Dish: ' + d.dish + '. Presentation: ' + (d.scene || '-') + ' Visible in the photo: ' + ((d.visible || []).join(', ') || '-') + '. Tone focus: ' + d.angle + '.\n' +
    'Review results:\n' + (lines.join('\n') || '(no valid candidate)') + '\n' +
    'Fix these problems and write THREE NEW, CLEARLY DIFFERENT alternatives in ' + LANG + '. Keep the strengths of the highest-scoring candidate. ' +
    'redTitle: the white headline, at most ' + TMAXW + ' words and ' + (CFG.title_max_chars || 44) + ' characters, a complete phrase about the main dish itself, appetizing, WITHOUT the dish name (it is printed separately below it), sentence case, no trailing period. ' +
    'caption: 1-2 short natural sentences, at least 40 characters, mentioning the dish name ("' + d.shortDish.toLocaleLowerCase(LOC) + '") naturally inside a sentence, using only details from the visible list and not listing serving items such as plates, bowls or glasses. ' +
    (banned ? 'Do not use these words or phrases: ' + banned + '. ' : '') + 'No prices, promotions, opening hours, addresses, emoji or hashtags. ' +
    'Write JSON only: {"options":[{"redTitle":"...","caption":"..."},{"redTitle":"...","caption":"..."},{"redTitle":"...","caption":"..."}]}';
};

// One Jev request per candidate, so each score is independent of the others
const d = $json;
const items = d.candidates.map((c, i) => ({json: {idx: i, body: jevBody(d, c)}}));
// No candidate passed the rules: send a single ping so the flow still reaches the decision node (which asks for a revision)
if (!items.length) items.push({json: {idx: -1, body: PING}});
return items;

const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
// ---- Jev (TypeSafe) shared definitions: a typed decision model. It never writes text and never sees images. ----
const JEV_MODEL = CFG.jev_model || 'typesafe/jev-1.13';
const JEV_ON = CFG.jev_enabled !== false;
const Q_OK = Number(CFG.jev_min_score) || 0.80; // best candidate below this score triggers one revision round
const TMAXW = CFG.title_max_words || 5;
const productLine = d => { const s = d.shortDish || ''; const p = String(CFG.product_prefix || '').trim(); return p && !s.toLocaleLowerCase(LOC).startsWith(p.toLocaleLowerCase(LOC)) ? p + ' ' + s : s; };
const jevQuestions = (kind) => {
  const q = {
    dish_match: {type: 'noul', instructions: 'The white headline (title) and the caption are Instagram copy for the restaurant dish named in "dish". Do they describe that dish (as presented in "presentation") and not a different food?', criteria: {true: 'Text is about the named dish', false: 'Text describes a different dish or contradicts the named dish'}},
