const captionFull = content.caption + '\n\n' + tags.join(' ');
return [{json: {base: src.base, kind: src.kind, hash: src.sourceHash, dish: content.dish, caption: content.caption, captionFull, imageFile: file,
  imageUrl: CFG.public_media_url + encodeURIComponent(file)}}];

// Dry run: the image was rendered but nothing goes to Instagram. The photo stays available for real runs.
const fs = require('fs');
const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const d = $('Render Image').first().json;
const p = CFG.data_dir + '/state/ledger.json';
const ledger = JSON.parse(fs.readFileSync(p, 'utf8'));
const entry = ledger.entries.find(e => e.base === d.base);
if (entry) { entry.status = 'dry_run'; entry.dryRunAt = new Date().toISOString();
  const tmp = p + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(ledger, null, 2)); fs.renameSync(tmp, p); }
return [{json: {dryRun: true, kind: d.kind, base: d.base, imageFile: d.imageFile, imageUrl: d.imageUrl}}];

const fs = require('fs');
const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const d = $('Render Image').first().json;
const p = CFG.data_dir + '/state/ledger.json';
const ledger = JSON.parse(fs.readFileSync(p, 'utf8'));
const entry = ledger.entries.find(e => e.base === d.base);
if (!entry) throw new Error('Ledger entry not found: ' + d.base);
entry.status = 'published'; entry.publishedAt = new Date().toISOString(); entry.mediaId = String($json.id || '');
if (!entry.mediaId) throw new Error('Meta did not return a media id');
const tmp = p + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(ledger, null, 2)); fs.renameSync(tmp, p);
return [{json: {ok: true, kind: d.kind, base: d.base, mediaId: entry.mediaId}}];

// HTML report with the image, the chosen copy, every candidate with its Jev score, and the reframe verdict.
// This node and the email node continue on error: a failed email never breaks publishing.
const fs = require('fs');
const CFG = $('Config').first().json;
const LOC = CFG.locale || 'en-US';
const LANG = CFG.language || 'English';
const c = $('Save Approved Copy').first().json;
const p = $('Render Image').first().json;
const dry = $('Dry Run: Mark Ledger').isExecuted;
const y = $('Save Published').isExecuted ? $('Save Published').first().json : {mediaId: ''};
const f = $('Reframe Decision').isExecuted ? $('Reframe Decision').first().json.frameCheck : null;
const framed = $('Save Reframe').first().json.frameOk === true;
const link = dry ? '' : ($json.permalink || '');
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const post = c.kind === 'post';
const ACCENT = CFG.accent_color || '#E63946';
// $now is in the workflow/instance timezone (set GENERIC_TIMEZONE or the workflow timezone)
let when; try { when = $now.setLocale(LOC).toLocaleString({dateStyle: 'long', timeStyle: 'short'}); } catch (e) { when = new Date().toISOString(); }
const LABELS = {dish_mismatch: 'dish mismatch', title_grammar: 'broken headline language', caption_grammar: 'broken caption language', ungrounded: 'detail not in photo',
  off_focus: 'headline not about the dish', appeal: 'flat headline', caption_appeal: 'flat caption', grammar: 'grammar', incomplete_title: 'unfinished headline', cliche: 'cliché', repeats_dish: 'repeats dish name'};
const pct = x => x == null ? '—' : Math.round(x * 100);
const td = 'padding:6px 8px;border-top:1px solid #eee;font-size:13px';
const rows = (c.rated || []).slice().sort((a, b) => (b.q == null ? 50 : b.q * 100) - (a.q == null ? 50 : a.q * 100)).map(x => {
  const chosen = x.id === c.chosenId;
  const note = chosen ? '<b style="color:#1a7f37">chosen</b>' : (x.gates && x.gates.length ? '<span style="color:#b42318">dropped: ' + esc(x.gates.map(g => LABELS[g] || g).join(', ')) + '</span>' : 'lower score');
  const diag = (x.diag || []).filter(g => !(x.gates || []).includes(g)).map(g => LABELS[g] || g).join(', ');
  return '<tr style="' + (chosen ? 'background:#f0f9f1' : '') + '"><td style="' + td + '">' + (x.round === 2 ? 'revision' : 'first') + '</td>' +
    '<td style="' + td + '"><b>' + esc(x.redTitle) + '</b>' + (post ? '<br><span style="color:#555">' + esc(x.caption) + '</span>' : '') +
    (diag ? '<br><span style="color:#8a6d00;font-size:12px">Jev note: ' + esc(diag) + '</span>' : '') + '</td>' +
    '<td style="' + td + ';text-align:center"><b>' + pct(x.q) + '</b></td>' +
    '<td style="' + td + ';font-size:12px">' + note + '</td></tr>';
}).join('') + (c.codeFails || []).map(x => '<tr><td style="' + td + '">' + (x.round === 2 ? 'revision' : 'first') + '</td><td style="' + td + ';color:#777">' + esc(x.redTitle) + '</td><td style="' + td + ';text-align:center;color:#777">—</td><td style="' + td + ';font-size:12px;color:#b42318">rule: ' + esc(x.fail) + '</td></tr>').join('');
const chosen = (c.rated || []).find(x => x.id === c.chosenId) || {};
let frameHtml;
if (!framed && !f) frameHtml = 'AI reframe could not be generated; the original photo was used.';
else if (f && !f.accept) frameHtml = '<span style="color:#b42318">AI reframe rejected; the original photo was used</span> — ' + esc(f.why);
else frameHtml = 'AI reframe approved' + (f && f.truthful != null ? ' — same dish: ' + pct(f.truthful) + '%, reframe quality: ' + (Math.round(f.quality * 10) / 10) + '/3' : '') + (f && f.status !== 'jev' ? ' (' + esc(f.status) + ')' : '');
if (f && (f.added.length || f.removed.length || f.defects.length)) frameHtml += '<br><span style="color:#8a6d00;font-size:12px">Gemini note: ' + esc([f.added.length ? 'added: ' + f.added.join(', ') : '', f.removed.length ? 'removed: ' + f.removed.join(', ') : '', f.defects.length ? 'defects: ' + f.defects.join(', ') : ''].filter(Boolean).join(' · ')) + '</span>';
const jevLine = c.jevStatus === 'unreachable' ? '<span style="color:#b42318">Jev was unreachable; the first candidate that passed the rule checks was used.</span>'
  : c.jevStatus === 'disabled' ? 'Jev is disabled (jev_enabled = false); the first candidate that passed the rule checks was used.'
  : (c.revised ? 'The first candidates did not score high enough; Gemini rewrote them from Jev\'s diagnoses and all candidates competed together.' : 'The best first-round candidate scored high enough right away.');
const kindName = post ? 'Post' : 'Story';
const prefix = String(CFG.product_prefix || '').trim();
const shortDish = c.dish.replace(/\s*\([^)]*\)\s*/g, ' ').trim();
const productLine = prefix && !shortDish.toLocaleLowerCase(LOC).startsWith(prefix.toLocaleLowerCase(LOC)) ? prefix + ' ' + shortDish : shortDish;
const subject = (dry ? '🧪 Dry run — ' : '✅ ') + CFG.brand_name + ' ' + kindName.toLowerCase() + (dry ? ' rendered (not published): ' : ' is live: ') + c.dish;
const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;max-width:640px;margin:0 auto;color:#1d1d1f">' +
 '<div style="background:' + esc(ACCENT) + ';color:#fff;padding:16px 20px;border-radius:10px 10px 0 0"><div style="font-size:13px;opacity:.85">' + esc(CFG.brand_name) + ' · Instagram · ' + kindName + '</div>' +
 '<div style="font-size:20px;font-weight:700;margin-top:4px">' + esc(c.dish) + (dry ? ' rendered (dry run)' : ' published') + '</div><div style="font-size:13px;opacity:.85;margin-top:2px">' + esc(when) + '</div></div>' +
 '<div style="border:1px solid #eee;border-top:0;padding:18px 20px;border-radius:0 0 10px 10px">' +
 (dry ? '<p style="margin:0 0 14px;color:#8a6d00">Dry run: nothing was sent to Instagram. Set <b>dry_run</b> to false in the Config node to publish.</p>'
   : (link ? '<p style="margin:0 0 14px"><a href="' + esc(link) + '" style="background:#1d1d1f;color:#fff;text-decoration:none;padding:9px 16px;border-radius:6px;font-size:14px;display:inline-block">Open on Instagram</a></p>'
   : '<p style="color:#b42318">Could not fetch the Instagram link (media id: ' + esc(y.mediaId) + ')</p>')) +
 '<img src="' + esc(p.imageUrl) + '" alt="Published image" style="width:100%;max-width:' + (post ? '420' : '300') + 'px;border-radius:8px;display:block;margin:0 0 16px">' +
 '<table style="border-collapse:collapse;width:100%;font-size:14px;margin-bottom:14px">' +
 '<tr><td style="padding:4px 0;color:#666;width:120px;vertical-align:top">Headline</td><td style="padding:4px 0"><b>' + esc(c.redTitle) + '</b></td></tr>' +
 '<tr><td style="padding:4px 0;color:#666;vertical-align:top">Product line</td><td style="padding:4px 0;color:' + esc(ACCENT) + '"><b>' + esc(productLine) + '</b></td></tr>' +
 (post ? '<tr><td style="padding:4px 0;color:#666;vertical-align:top">Caption</td><td style="padding:4px 0;white-space:pre-wrap">' + esc(p.captionFull) + '</td></tr>' : '') +
 '<tr><td style="padding:4px 0;color:#666;vertical-align:top">Source</td><td style="padding:4px 0;font-size:13px">' + esc(c.sourceFile) + ' · dish from: ' + esc(c.dishSource) + ' · tone: ' + esc(c.angle) + '</td></tr>' +
 '<tr><td style="padding:4px 0;color:#666;vertical-align:top">Reframe</td><td style="padding:4px 0;font-size:13px">' + frameHtml + '</td></tr></table>' +
 '<div style="font-size:15px;font-weight:700;margin:18px 0 6px">Jev copy review — chosen score ' + pct(chosen.q) + '/100</div>' +
 '<div style="font-size:13px;color:#444;margin-bottom:8px">' + jevLine + '</div>' +
 '<table style="border-collapse:collapse;width:100%"><tr style="background:#fafafa"><th style="text-align:left;padding:6px 8px;font-size:12px;color:#666">Round</th><th style="text-align:left;padding:6px 8px;font-size:12px;color:#666">Candidate</th><th style="padding:6px 8px;font-size:12px;color:#666">Score</th><th style="text-align:left;padding:6px 8px;font-size:12px;color:#666">Status</th></tr>' + rows + '</table>' +
 '<p style="font-size:11px;color:#999;margin-top:18px">Score: weighted average of Jev (' + esc(CFG.jev_model || 'typesafe/jev-1.13') + ') answers on headline focus, appetite appeal, ' + esc(LANG) + ' naturalness' + (post ? ', caption faithfulness to the photo and caption appeal' : '') + '. Media id ' + esc(y.mediaId || '—') + '</p>' +
 '</div></div>';
const file = CFG.data_dir + '/out/' + p.imageFile;
const binary = {};
try { binary.data = await this.helpers.prepareBinaryData(fs.readFileSync(file), p.imageFile, 'image/jpeg'); } catch (e) {}
return [{json: {subject, html}, binary}];
